b = Block('b')
def put(n,part,condition,answer,steps,p,v,views=None,**kw):
    printed=kw.pop('printed', [178] if n<=677 else [178,179] if n<=680 else [179] if n<=687 else [180] if n<=696 else [184] if n<=704 else [185])
    b.add(n,part,condition,answer,steps,p,v,views,printed=printed,**kw)

def hyp(bc,ac,footname='H'):
    return {'A':[0,0],'B':[bc+ac,0],'C':[bc,math.sqrt(bc*ac)],footname:[bc,0]}
def hv(footname='H'):
    return sc(['A','B','C',footname],tri()+[['C',footname]],rightAngles=[rt('A','C','B'),rt('C',footname,'B')])
def hc(footname='H'):
    return [perp('A','C','B','C'),perp('C',footname,'A','B'),col('A',footname,'B')]

