put(692,'single','Постройте треугольник по двум углам и биссектрисе, проведённой из вершины меньшего из этих данных углов.','Постройте подобный вспомогательный треугольник, на биссектрисе меньшего данного угла отложите заданную длину и через её конец проведите прямую, параллельную противоположной стороне.',[
 row('Как выбрать вспомогательный треугольник?','Пусть данные углы α < β, длина биссектрисы l > 0. Постройте AB₁C₁ с ∠A = α и ∠B₁ = β, выбрав AB₁ произвольно. Это возможно при α > 0 и α + β < 180°.','Построение треугольника по стороне и двум прилежащим углам.',[38,72]),
 row('Из какой вершины провести биссектрису?','Из A, поскольку именно α — меньший из двух данных углов. Постройте AD₁, где D₁ лежит на B₁C₁.','Построение биссектрисы угла.',23),
 row('Как задать нужный размер?','На луче AD₁ отложите AD = l, равный данному отрезку PQ. Точка D может лежать как до D₁, так и за D₁.','Перенесение заданной длины циркулем.',23),
 row('Как завершить построение и доказать единственность?','Через D проведите BC ∥ B₁C₁ до пересечения с лучами AB₁ и AC₁. Тогда ABC ∼ AB₁C₁, углы A и B равны α и β, а AD — нужная биссектриса. Все треугольники с этими углами подобны; отношение соответствующих биссектрис равно коэффициенту подобия, поэтому заданное l определяет единственный размер. Зеркальное построение даёт равный треугольник.','Первый признак подобия и метод подобия.',[66,72])],p,v,[f,g,h,j],checks=[ang('B1','A','C1',35),ang('A','B1','C1',65),ang('B1','A','D1',17.5),ang('D1','A','C1',17.5),col('B1','D1','C1'),col('A','D1','D'),col('B','D','C'),par('B','C','B1','C1'),equal(('A','D'),('P','Q'))],cases=[(reflect_scene(p),j,'Зеркальное расположение',4,[equal(('A','D'),('P','Q')),par('B','C','B1','C1')])],labels={'B1':'B₁','C1':'C₁','D1':'D₁'},offsets={'D1':[2,7],'D':[2,7]},notes=['Условия существования: 0° < α < β, α + β < 180°, l > 0. При равных данных углах слово «меньшего» не выбирает вершину; обе вершины равнозначны и дают равные треугольники. Числа 35° и 65° используются только для точного примера чертежа, не как дополнительные данные.'])

def height_construction(cx,cy,k=1.5):
    q=dict(A1=[0,0],B1=[6,0],C=[cx,cy],H1=[cx,0]);q.update(A=mix(q['C'],q['A1'],k),B=mix(q['C'],q['B1'],k),H=mix(q['C'],q['H1'],k));return q
