# 698: the neutral view contains only two segments in the requested ratio.
# The triangle is built after the learner opens the construction step.
for part,kind,small,large,given in [
 ('а','tg',1,2,'tg α =1/2'),('б','tg',3,4,'tg α =3/4'),
 ('в','cos',1,5,'cos α =0,2'),('г','cos',2,3,'cos α =2/3'),
 ('д','sin',1,2,'sin α =1/2'),('е','sin',2,5,'sin α =0,4')]:
    if kind=='tg': a,adj=small,large
    elif kind=='cos': a,adj=math.sqrt(large*large-small*small),small
    else: a,adj=small,math.sqrt(large*large-small*small)
    p=tright(a,adj);span=max(a,adj,large)
    p.update(P=[-span*.1,-span*.5],Q=[small-span*.1,-span*.5],R=[-span*.1,-span*.9],S=[large-span*.1,-span*.9])
    v=sc('PQRS',[['P','Q'],['R','S']])
    if kind=='tg':
        f=more(v,'ABC',[['A','C'],['C','B']],rightAngles=[rt('A','C','B')]);g=more(f,segs=[['A','B']],angleArcs=[arc('A','C','B',r=4)])
        steps=[row('Как представить заданную дробь отрезками?',f'Выберите единицу длины u и отложите PQ ={small}u, RS ={large}u. Их отношение равно {small}/{large}.','Число задаёт отношение длин; выбор единицы не меняет угол.',[63,74]),
          row('Как построить два катета?','Постройте прямой угол C. На одном его луче отложите CA =RS, на другом — CB =PQ. Оба отрезка положительны.','Построение перпендикуляра и отрезка, равного данному.',23),
          row('Какой угол является искомым?',f'Соедините A и B. Для α =∠CAB имеем tg α =CB/CA =PQ/RS ={small}/{large}. Построение в другой полуплоскости даёт равный острый угол.','Определение тангенса; равенство прямоугольных треугольников по двум катетам.',74)]
        answer=f'Постройте перпендикулярные катеты CA ={large}u и CB ={small}u; искомый угол — ∠CAB.'
        views=[v,f,g];checks=[ratio('B','C','A','C',small/large)]
    else:
        # On the second step only the known leg has been laid off.
        if kind=='cos':
            f=more(v,'AC',[['A','C']]);g=more(f,'B',[['C','B'],['A','B']],rightAngles=[rt('A','C','B')],angleArcs=[arc('A','C','B',r=4)])
            construct='Отложите CA =PQ. В точке C восстановите перпендикуляр к CA. Окружность с центром A и радиусом RS пересечёт его в двух точках; выберите любую из них, B.'
            relation=f'cos ∠CAB =CA/AB =PQ/RS ={small}/{large}'
            answer=f'Возьмите CA ={small}u и AB ={large}u; вершину B получите пересечением перпендикуляра в C с окружностью центра A радиуса {large}u. Искомый угол — ∠CAB.'
            checks=[ratio('A','C','A','B',small/large)]
        else:
            f=more(v,'BC',[['B','C']]);g=more(f,'A',[['A','C'],['A','B']],rightAngles=[rt('A','C','B')],angleArcs=[arc('A','C','B',r=4)])
            construct='Отложите CB =PQ. В точке C восстановите перпендикуляр к CB. Окружность с центром B и радиусом RS пересечёт его в двух точках; выберите любую из них, A.'
            relation=f'sin ∠CAB =CB/AB =PQ/RS ={small}/{large}'
            answer=f'Возьмите CB ={small}u и AB ={large}u; вершину A получите пересечением перпендикуляра в C с окружностью центра B радиуса {large}u. Искомый угол — ∠CAB.'
        checks=[ratio('B','C','A','B',small/large)] if kind=='sin' else checks
        steps=[row('Как заменить десятичное число или дробь отношением длин?',f'Возьмите отрезки PQ ={small}u и RS ={large}u, где u — произвольная единица. Здесь 0 <PQ <RS, что необходимо для отношения катета к гипотенузе.','Синус и косинус острого угла лежат между0 и1.',74),
          row('Как расположить известный катет?',('Отложите CA =PQ; это катет, прилежащий к искомому углу.' if kind=='cos' else 'Отложите CB =PQ; это катет, противолежащий искомому углу.'),'Выбор катета по определению заданной функции.',74),
          row('Как завершить построение и проверить его?',construct+' Соедините вершины. Тогда '+relation+'. Так как RS >PQ, пересечения существуют и дают два зеркальных равных острых угла.','Построение прямоугольного треугольника по гипотенузе и катету; определение функции.',74)]
        views=[v,f,g]
    q={k:[z[0],-z[1]] for k,z in tright(a,adj).items()}
    cv=trview();checks += [perp('A','C','B','C'),ratio('P','Q','R','S',small/large)]
    tput(698,part,'Постройте острый угол α, если '+given+'.',answer,steps,p,v,views,checks=checks,cases=[(q,cv,'Зеркальное построение: тот же острый угол',3,[perp('A','C','B','C'),ratio('B','C','A','C',a/adj)])],offsets={**troff(),'P':[-4,3],'Q':[4,3],'R':[-4,3],'S':[4,3]},notes=['Отрезки PQ и RS изображают выбранные кратные произвольной единицы; они не добавляют числовых условий. Окружность, используемая циркулем, описана в построении; показаны её нужное пересечение и радиус-гипотенуза.'])

